// PROTOTYPE B — Hub-and-spoke "rooms": a project home with four rooms; each opens a focused workspace; breadcrumbs + ⌘K to move; shots are a focus view with ←/→.
function crumbs(){const c=[`<a onclick="go({view:'home',scene:null,shot:null})" style="cursor:pointer;color:var(--acc)">${STATE==='new'?'Untitled project':'The Landlord Sketch'}</a>`];
 const v=U.view;
 if(['input','interview','treatment','beats','narrative','story'].includes(v)){c.push(`<a onclick="go({view:'story'})" style="cursor:pointer;color:var(--acc)">Story</a>`);if(v!=='story')c.push(phase(v).n)}
 if(v==='world')c.push('World');
 if(['prod','scene','shot'].includes(v)){c.push(`<a onclick="go({view:'prod',scene:null,shot:null})" style="cursor:pointer;color:var(--acc)">Production</a>`);if(U.scene!=null)c.push(v==='shot'?`<a onclick="go({view:'scene',shot:null})" style="cursor:pointer;color:var(--acc)">Scene ${U.scene+1}: ${SCENES[U.scene].title}</a>`:`Scene ${U.scene+1}: ${SCENES[U.scene].title}`);if(v==='shot')c.push('Shot '+U.shot)}
 if(v==='review')c.push('Review & Export');
 return c.join(' <span class="mut">›</span> ')}
function viewB(){
 const hdr=`<div class="row" style="padding:10px 16px;background:#fff;border-bottom:1px solid var(--line)"><button class="ghost" onclick="back()">←</button><div style="font-size:14px">${crumbs()}</div><span class="sp"></span>${STATE==='new'?'':staleNote()}<button onclick="go({palette:true},1);setTimeout(()=>document.getElementById('q').focus(),30)">Jump to… <span class="kbd">⌘K</span></button></div>`;
 let body='';
 if(U.view==='home')body=homeB(); else if(U.view==='story')body=storyB(); else if(U.view==='prod')body=prodB(); else if(U.view==='scene')body=sceneB(); else if(U.view==='shot')body=shotB();
 else body=`<div class="scroll" style="flex:1">${phasePage(U.view)}</div>`;
 return hdr+body+(U.palette?palette():'')}
function roomCard(t,sub,st,onclick,extra){return `<div class="card pad" style="cursor:pointer;flex:1;min-width:240px" onclick="${onclick}"><div class="row"><h3 style="margin:0">${t}</h3><span class="sp"></span>${st}</div><div class="mut" style="margin:4px 0 10px">${sub}</div>${extra||''}</div>`}
function homeB(){
 const t=totals(),n=SHOTS.length,mid=STATE!=='new';
 const next=mid?`<div class="card pad row" style="background:#eef1fd;border-color:#d5dcf6"><div><div class="sm mut">SUGGESTED NEXT</div><b>5 shots failed and 7 need a take picked in scenes 7–9</b></div><span class="sp"></span><button class="pri" onclick="go({view:'scene',scene:7})">Open scene 8</button><button onclick="go({view:'world'})">Define 2 missing locations</button></div>`
  :`<div class="card pad" style="background:#eef1fd;border-color:#d5dcf6"><h2 style="margin:0 0 4px">Welcome — start with whatever you have</h2><div class="mut" style="margin-bottom:10px">Four rooms hold the whole film. They’re all open from the start; you just begin in Story. Skip anything you don’t need.</div>
  <div class="row" style="flex-wrap:wrap;gap:8px">${['A rough idea or notes','A story / treatment','An outline / beats','A screenplay','Storyboards / previs'].map(x=>`<button class="pri" onclick="go({view:'input'})">${x}</button>`).join('')}</div><div class="sm mut" style="margin-top:8px">Coach marks: ① Story → ② World → ③ Production → ④ Review (dismiss any time)</div></div>`;
 const storyDots=PHASES.filter(p=>p.grp==='story').map(p=>`<span class="chip ${phSt(p.id)}" title="${PH_NOTE[p.id]||p.d}">${p.n}</span>`).join(' ');
 return `<div class="scroll" style="flex:1"><div class="pad" style="max-width:1100px;margin:0 auto">${next}
  <div class="row" style="margin:14px 0;align-items:stretch;flex-wrap:wrap">
   ${roomCard('Story','Input → Master Narrative',chip(phSt('narrative')==='done'?'done':'prog'),"go({view:'story'})",`<div class="row" style="flex-wrap:wrap;gap:4px">${storyDots}</div>`)}
   ${roomCard('World',mid?PH_NOTE.world:'Characters, locations, props, style',chip(phSt('world')),"go({view:'world'})",mid?`<div class="bar"><i style="width:68%;background:var(--ok)"></i><i style="width:18%;background:#cfcfd6"></i></div>`:'')}
   ${roomCard('Production',n?`${SCENES.filter(s=>s.shots.length).length} of 22 scenes planned · ${n} shots`:'Scenes, shots, frames, takes',chip(n?'prog':'todo'),"go({view:'prod'})",n?stackBar(t,n,10):'')}
   ${roomCard('Review & Export',mid?PH_NOTE.review:'Watch, fix, export',chip(phSt('review')),"go({view:'review'})")}
  </div>
  ${mid?`<div class="card pad"><div class="row"><b>Whole film</b><span class="sp"></span>${runtimeMeter()}</div><div style="margin:8px 0">${SCENES.map(s=>`<span title="Scene ${s.n}" onclick="go({view:'scene',scene:${s.i}})" style="display:inline-block;width:${Math.max(18,s.dur*2.2)}px;margin:1px;cursor:pointer">${s.shots.length?stackBar(scProg(s),s.shots.length,14):'<div class="bar" style="height:14px;background:repeating-linear-gradient(45deg,#e6e6ea,#e6e6ea 3px,#fff 3px,#fff 6px)"></div>'}</span>`).join('')}</div><div class="row sm" style="gap:12px;flex-wrap:wrap">${legend()}</div></div>`:''}</div></div>`}
function storyB(){return `<div class="scroll" style="flex:1"><div class="pad" style="max-width:820px;margin:0 auto"><h2 style="margin-top:0">Story</h2>${PHASES.filter(p=>p.grp==='story').map(p=>`<div class="card pad row" style="margin:8px 0;cursor:pointer;${['skipped','bypassed'].includes(phSt(p.id))?'border-style:dashed;background:#fafafb':''}" onclick="go({view:'${p.id}'})"><div style="width:150px"><b>${p.n}</b></div>${chip(phSt(p.id))}<span class="mut sm sp">${PH_NOTE[p.id]||p.d}</span>›</div>`).join('')}</div></div>`}
function prodB(){
 if(!SHOTS.length)return `<div class="pad mut">Production opens once the Master Narrative is accepted.</div>`;
 return `<div class="scroll" style="flex:1"><div class="pad"><div class="row" style="margin-bottom:10px"><h2 style="margin:0">Production</h2><span class="sp"></span><button>Draft shot plans for all</button><button>Generate all approved shots…</button><button>Compare scenes</button></div>
 <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:10px">${SCENES.map(s=>`<div class="card pad" style="cursor:pointer" onclick="go({view:'scene',scene:${s.i}})"><div class="row"><b>${s.n}</b><span style="flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${s.title}</span></div><div class="sm mut">${s.shots.length?s.shots.length+' shots · '+fmt(s.dur):'No shot plan'}</div><div style="margin:6px 0;min-height:20px">${s.shots.map(x=>sq(x)).join('')}</div>${s.shots.length?stackBar(scProg(s),s.shots.length,6):''}</div>`).join('')}</div></div></div>`}
function sceneB(){const s=SCENES[U.scene];
 return `<div class="scroll" style="flex:1"><div class="pad"><div class="row"><button onclick="go({scene:${Math.max(0,s.i-1)}},1)">‹ Scene ${Math.max(1,s.n-1)}</button><h2 style="margin:0">Scene ${s.n}: ${s.title}</h2><span class="mut">${s.slug} · ${fmt(s.dur)}</span><span class="sp"></span><button onclick="go({scene:${Math.min(21,s.i+1)}},1)">Scene ${Math.min(22,s.n+1)} ›</button></div>
 <div class="row" style="margin:10px 0">${s.shots.length?`<div style="width:300px">${stackBar(scProg(s),s.shots.length,10)}</div>`:''}<button>Draft shot plan</button><button>Frames for scene</button><button class="pri">Generate approved shots…</button><button>Play scene</button></div>
 ${s.shots.length?`<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(170px,1fr));gap:10px">${s.shots.map(sh=>`<div class="card" style="cursor:pointer;overflow:hidden" onclick="go({view:'shot',shot:'${sh.id}'})">${thumb(sh,170,96).replace('border-radius:5px','border-radius:0')}<div class="pad" style="padding:6px 8px"><b>${sh.id}</b> ${sh.title}<div class="row sm"><i class="dot ${sh.st==='generating'?'gen':''}" style="background:${SHOT_STATES[sh.st][1]}"></i>${SHOT_STATES[sh.st][0]} ${sh.stale?'<span class="stale">?</span>':''}</div></div></div>`).join('')}</div>`:'<div class="banner">No shot plan yet for this scene — an AI draft is one click away.</div>'}</div></div>`}
function shotB(){const sh=shotById(U.shot),s=SCENES[sh.sc];
 return `<div class="scroll" style="flex:1"><div style="max-width:980px;margin:0 auto"><div class="row" style="padding:12px 16px"><button onclick="go({shot:'${(s.shots[sh.k-1]||sh).id}'},1)">← prev <span class="kbd">←</span></button><button onclick="go({shot:'${(s.shots[sh.k+1]||sh).id}'},1)">next <span class="kbd">→</span> →</button><span class="mut sm">${sh.k+1} of ${s.shots.length} in scene ${s.n}</span></div><div class="card">${shotDetail(sh)}</div><div class="pad"><div class="sm mut">Scene filmstrip</div><div class="row" style="gap:4px;flex-wrap:wrap">${s.shots.map(x=>`<div onclick="go({shot:'${x.id}'},1)" style="cursor:pointer;${x.id===sh.id?'outline:2px solid var(--ink)':''}">${thumb(x,70,40)}</div>`).join('')}</div></div></div></div>`}
function palette(){const q=(document.getElementById('q')||{}).value||'';
 const items=[...PHASES.map(p=>({t:p.n,s:'Phase · '+(PH_NOTE[p.id]||p.d),a:`go({view:'${p.id==='scenes'||p.grp==='prod'?'prod':p.id}',palette:false})`})),...SCENES.map(s=>({t:`Scene ${s.n}: ${s.title}`,s:s.slug,a:`go({view:'scene',scene:${s.i},palette:false})`})),...SHOTS.map(s=>({t:'Shot '+s.id+' '+s.title,s:SHOT_STATES[s.st][0],a:`go({view:'shot',scene:${s.sc},shot:'${s.id}',palette:false})`}))];
 const m=items.filter(i=>(i.t+' '+i.s).toLowerCase().includes(q.toLowerCase())).slice(0,9);
 return `<div style="position:fixed;inset:0;background:#0006;z-index:500;display:flex;justify-content:center;padding-top:90px" onclick="U.palette=false;render()"><div class="card" style="width:560px;height:max-content" onclick="event.stopPropagation()"><input id="q" value="${esc(q)}" oninput="render();const e=document.getElementById('q');e.focus();e.setSelectionRange(99,99)" placeholder="Jump to a phase, scene, shot, entity… try 8.3" style="width:100%;border:0;border-bottom:1px solid var(--line);padding:12px;font-size:14px;outline:0">${m.map(i=>`<div class="row pad" style="padding:7px 12px;cursor:pointer" onclick="${i.a}"><b>${i.t}</b><span class="sp"></span><span class="mut sm">${i.s}</span></div>`).join('')}</div></div>`}
